package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's plans. Generating makes, for each plan in the order they were added, a draft claim of its amount on
 * each of its plan dates up to its end and the sheet's today that has none yet, dated that day with an empty note, by
 * every rule of the claim form; a date the form refuses is skipped and tried again next time.
 */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final Audit audit;
    private final TransactionTemplate tx;

    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims, SheetService sheets,
            Audit audit, PlatformTransactionManager transactions) {
        this.plans = plans;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
        this.tx = new TransactionTemplate(transactions);
    }

    /** The sheet's plans in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /**
     * Adds a plan for the person. Refused when the amount is negative or has more than two decimals, the interval is
     * less than one day, or the end is before the start.
     */
    @Transactional
    public Plan add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every,
            LocalDate end) {
        if (amount == null || amount.signum() < 0 || amount.stripTrailingZeros().scale() > 2
                || amount.precision() - amount.scale() > 12) {
            throw refused("Enter an amount of at least 0 with up to two decimals.");
        }
        if (every == null || every < 1) {
            throw refused("Enter a whole number of days of at least 1.");
        }
        if (start == null || end == null) {
            throw refused("Enter a start date and an end date.");
        }
        if (end.isBefore(start)) {
            throw refused("The end date is before the start date.");
        }
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        BigDecimal scaled = amount.setScale(2, RoundingMode.UNNECESSARY);
        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, scaled, start, every, end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName() + " amount="
                + scaled.toPlainString() + " start=" + start + " every=" + every + " end=" + end);
        return saved;
    }

    /** What a generate made: the claims, in the order they were made, and every plan of the sheet as it stands. */
    public record Generated(List<Claim> claims, List<Plan> plans) {
    }

    /**
     * Makes the plans' claims. Each claim is made in a change of its own, so one the claim form refuses changes
     * nothing and the others still go through.
     */
    public Generated generate(String by, String sheetId) {
        LocalDate today = sheets.load(sheetId).getToday();
        List<Claim> made = new ArrayList<>();
        for (Plan plan : tx.execute(s -> plans.findBySheetIdOrderByIdAsc(sheetId))) {
            LocalDate last = plan.getEnd().isBefore(today) ? plan.getEnd() : today;
            for (LocalDate on = plan.getStart(); !on.isAfter(last); on = on.plusDays(plan.getEvery())) {
                if (plan.hasMade(on)) {
                    continue;
                }
                LocalDate date = on;
                try {
                    made.add(tx.execute(s -> {
                        Plan current = plans.findById(plan.getId()).orElseThrow();
                        if (current.hasMade(date)) {
                            return null;
                        }
                        Claim claim = claims.add(by, sheetId, current.getPersonId(), current.getAmount(), date, "",
                                null, null, null);
                        current.markMade(date);
                        plans.saveAndFlush(current);
                        return claim;
                    }));
                } catch (ResponseStatusException refused) {
                    // the claim form refused this date: it is tried again next time
                }
            }
        }
        made.removeIf(c -> c == null);
        return new Generated(made, list(sheetId));
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
    }
}
-- A person's plans: an amount, made a draft claim on each plan date from the start, every so many days, to the end.
-- Each plan date a claim was made on is kept once, so generating again makes none for it; a date the claim form
-- refused is not kept and is tried again the next time.
CREATE TABLE plan (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    start_date DATE           NOT NULL,
    every_days INT            NOT NULL CHECK (every_days >= 1),
    end_date   DATE           NOT NULL,
    CHECK (end_date >= start_date)
);
CREATE INDEX plan_sheet ON plan (sheet_id, id);

CREATE TABLE plan_claim (
    plan_id BIGINT NOT NULL REFERENCES plan (id) ON DELETE CASCADE,
    on_date DATE   NOT NULL,
    PRIMARY KEY (plan_id, on_date)
);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, Injectable, computed, inject, input, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from '../claims/claims';

export interface PlanView {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number;
  end: string;
  // How many claims the plan has made so far.
  generated: number;
}

// The plans of the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class PlanStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly list = signal<readonly PlanView[]>([]);

  /** Re-read the sheet's plans from the store. */
  async load(sheet: string): Promise<void> {
    this.list.set([]);
    const l = await firstValueFrom(this.http.get<PlanView[]>(`/api/sheets/${encodeURIComponent(sheet)}/plans`));
    if (this.session.sheetId() === sheet) this.list.set(l);
  }

  async add(sheet: string, personId: number, form: { amount: string; start: string; every: number; end: string }): Promise<void> {
    const p = await firstValueFrom(
      this.http.post<PlanView>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/plans`, form),
    );
    if (this.session.sheetId() === sheet) this.list.update((l) => [...l.filter((x) => x.id !== p.id), p]);
  }

  /** Makes the plans' claims up to the sheet's today: the claims made, in the order they were made. */
  async generate(sheet: string): Promise<Claim[]> {
    const g = await firstValueFrom(
      this.http.post<{ claims: Claim[]; plans: PlanView[] }>(`/api/sheets/${encodeURIComponent(sheet)}/plans/generate`, null),
    );
    if (this.session.sheetId() === sheet) this.list.set(g.plans);
    return g.claims;
  }
}

